class _UnixReadPipeTransport(transports.ReadTransport):

    max_size = 256 * 1024  # max bytes we read in one event loop iteration

    def __init__(self, loop, pipe, protocol, waiter=None, extra=None):
        super().__init__(extra)
        self._set_nonblocking(pipe.fileno())
        self._pipe = pipe
        self._protocol = protocol
        self._waiter = waiter
        self._buffer = b''
        self._buffer_size = 0
        self._eof = False
        self._loop = loop
        self._transport = self
        self._protocol.connection_made(self)

    def pause_writing(self):
        self._pipe.close()

    def resume_writing(self):
        self._pipe = os.pipe()
        self._set_nonblocking(self._pipe[0])
        self._set_nonblocking(self._pipe[1])
        self._transport = self  # Reassign to self to update the transport

    def write(self, data):
        if self._eof:
            raise ConnectionResetError("Cannot write to a closed transport")
        if not self._pipe[1].fileno():
