                        value = datetime(*dt)
                row.append(value)
            data.append(row)
        return simpleParser(data, header=header, index_col=index_col,
                            na_values=na_values).toDataMatrix()

def parseExcel(filepath, header=None, indexCol=0, sheetname=None, **kwds):
    """
    Parse Excel file into a DataFrame object. 
    - `header` (int): 0-based index of the header row (default 0).
    - `indexCol` (int): 0-based index of the column to use as the index (default 0).
    - `sheetname` (str): name of the sheet to parse (default 'Sheet1').
    - `skiprows` (int or list): rows to skip (default None).
    - `na_values` (list or set): additional NA values to recognize (default None).

    Returns:
