class ModuleContextCheckpointState:
    nn_modules: Dict[str, torch.nn.Module] = {}

    def __init__(self, nn_modules: Dict[str, torch.nn.Module] = None):
        if nn_modules is None:
            nn_modules = {}
        self.nn_modules = nn_modules

    """
    Produces a delta against another ModuleContextCheckpointState.

    Returns None if no delta is found, otherwise, return a set() of mismatched
    module key names.
    """

    def diff(self, other: 'ModuleContextCheckpointState') -> set:
        return self.nn_modules.keys() - other.nn_modules.keys()

    def __eq__(self, other: 'ModuleContextCheckpointState') -> bool:
        return self.diff(other) == set()

    def __repr__(self):
        return f"ModuleContextCheckpointState(nn_modules={self.nn_modules})"


class ModuleContext(Checkpointable[ModuleContextCheckpointState]):
