    for unary_op_name in unary_op_set:
        res_array.append(getattr(torch, unary_op_name)(x))

    self.assertEqual(invoke_count, unary_op_set.__len__())
    for ref, res in zip(ref_array, res_array):
        self.assertEqual(ref, res)

