        torch.vmap(torch.vmap(fn, randomness="same"), randomness="same")(x)
        with self.assertRaises(torch._dynamo.exc.RecompileError):
            torch.vmap(torch.vmap(fn, randomness="same"), randomness="error")(x)

    @config.patch(capture_func_transforms=True)
    @config.patch(error_on_recompile=True)
    def test_vmap_recompile_with_randomness(self):
        @torch.compile(backend="eager")
        def fn(x):
            return torch.vmap(lambda x: x.sin())(x)

        x = torch.zeros(3, 3, 4, 5)
        torch.vmap(fn, randomness="same")(x)
        with self.assertRaises(torch._dynamo.exc.RecompileError):
            torch.vmap(fn, randomness="different")(x)

    @config.patch(capture_func_transforms=True)
    def test_vmap_get_wrapped(self):
        counters.clear()

        def g(x):
            return x.sin()

        # Test that the vmap wrapper correctly wraps the function
        wrapped = torch.compile(g, backend="eager")
        self.assertEqual(wrapped(torch.zeros(3, 3)), torch.zeros(3, 3).sin())
        self.assertEqual(wrapped(torch.ones(3, 3)), torch.ones(3, 3).sin())

        # Test that the wrapper can be used with vmap
        vmap_wrapped = torch.vmap(wrapped)
        self.assertEqual(vmap_wrapped(torch.zeros(3, 3)), torch.vmap(lambda x: x.sin)(torch.zeros(3, 3)))
        self.assertEqual(vmap_wrapped(torch.ones(3, 3)), torch.vmap(lambda x: x.sin)(torch.ones(3, 3)))

        # Test that the wrapper respects the error_on_recompile setting
        with self.assertRaises(torch._dynamo.exc.RecompileError):
            torch.vmap(wrapped, randomness="different")(torch.zeros(3, 3))
        with self.assertRaises(torch._dynamo.exc.RecompileError):
            torch.vmap(wrapped, randomness="error")(torch.zeros(3, 3))

        # Test that the wrapper works with different randomness settings
        torch.vmap(wrapped, randomness="same")(torch.zeros(3, 3))
        torch.vmap(wrapped, randomness="same")(torch.ones(3, 3))
        with self.assertRaises(torch._dynamo.exc.RecompileError):
            torch.vmap(wrapped, randomness="different")(torch.zeros(3, 3))
        with self.assertRaises(torch._dynamo.exc.RecompileError):
