def test_hooks_allowed_modules(self):
    class ToyModel(torch.nn.Module):
        def __init__(self):
            super().__init__()
            self.net = torch.nn.Sequential(
                torch.nn.Linear(10, 10000),  # Simplified for clarity
                torch.nn.ReLU(),
                torch.nn.Linear(10000, 5),  # Simplified for clarity
                torch.nn.ReLU(),
            )

        def forward(self, x):
            return self.net(x)

    model = ToyModel()
    forward_handles = {}
    activations = dict()

    def save_activations(name, mod, inp, out):
        activations[name] = inp

    for name, module in model.named_modules():
        forward_handles[name] = module.register_forward_hook(partial(save_activations, name))

    model = torch.compile(model, backend="aot_eager")

    for i in range(2):
        # Second iteration is key, hooks would have fired during AOT trace
        # on first iteration
        activations.clear()
        x = torch.randn((20, 10))
        pred = model(x)
        loss = pred.sum()
        loss.backward()

    print(f"Recorded Layers: {activations.keys()}\n\n")
    print(f"Expected Layers: {forward_handles.keys()}")
    self.assertTrue(activations.keys() == forward_handles.keys())

